mapper.insert:
INSERT INTO company_share (company_id, workspace_id, granted_by, can_edit)
SELECT c.id, target_workspace.id, #{grantedBy}, #{canEdit}
FROM company c
JOIN JSON_TABLE(#{orgWorkspaceIdsJson}, '$[*]' COLUMNS(id INT PATH '$')) owner_workspace
  ON owner_workspace.id = c.workspace_id
JOIN JSON_TABLE(#{orgWorkspaceIdsJson}, '$[*]' COLUMNS(id INT PATH '$')) target_workspace
  ON target_workspace.id = #{targetWorkspaceId}
WHERE c.id = #{id} AND c.workspace_id = #{workspaceId}
  AND c.archived_at IS NULL
ON DUPLICATE KEY UPDATE can_edit = #{canEdit}, granted_by = #{grantedBy}

INSERT INTO person_share (person_id, workspace_id, granted_by, can_edit)
SELECT p.id, target_workspace.id, #{grantedBy}, #{canEdit}
FROM person p
JOIN JSON_TABLE(#{orgWorkspaceIdsJson}, '$[*]' COLUMNS(id INT PATH '$')) owner_workspace
  ON owner_workspace.id = p.workspace_id
JOIN JSON_TABLE(#{orgWorkspaceIdsJson}, '$[*]' COLUMNS(id INT PATH '$')) target_workspace
  ON target_workspace.id = #{targetWorkspaceId}
WHERE p.id = #{id} AND p.workspace_id = #{workspaceId}
  AND p.provision_ceased_at IS NULL
  AND p.archived_at IS NULL
ON DUPLICATE KEY UPDATE can_edit = #{canEdit}, granted_by = #{grantedBy}

INSERT INTO pipeline_share (pipeline_id, workspace_id, granted_by, can_edit)
SELECT pl.id, target_workspace.id, #{grantedBy}, #{canEdit}
FROM pipeline pl
JOIN JSON_TABLE(#{orgWorkspaceIdsJson}, '$[*]' COLUMNS(id INT PATH '$')) owner_workspace
  ON owner_workspace.id = pl.workspace_id
JOIN JSON_TABLE(#{orgWorkspaceIdsJson}, '$[*]' COLUMNS(id INT PATH '$')) target_workspace
  ON target_workspace.id = #{targetWorkspaceId}
WHERE pl.id = #{id} AND pl.workspace_id = #{workspaceId}
ON DUPLICATE KEY UPDATE can_edit = #{canEdit}, granted_by = #{grantedBy}

